#!/usr/bin/env python3"""Regression checks for the Exists MP3-aligned interactive tab."""from __future__ import annotationsimport jsonimport reimport subprocessimport tempfilefrom pathlib import PathROOT = Path(__file__).resolve().parents[1]DATA_PATH = ROOT / "tabs" / "exists-dirantai-digelangi-rindu-data.js"HTML_PATH = ROOT / "tabs" / "exists-dirantai-digelangi-rindu.html"CATALOG_PATH = ROOT / "tab-catalog.json"PREFIX = "window.KC_EXISTS_TRANSCRIPTION="DRUM_KEYS = {"h", "s", "k", "c", "t"}def load_transcription() -> dict:    source = DATA_PATH.read_text(encoding="utf-8").strip()    assert source.startswith(PREFIX) and source.endswith(";"), DATA_PATH    return json.loads(source[len(PREFIX) : -1])def validate_note_track(    name: str, bars: list[list[list[int]]], *, polyphonic: bool = False) -> int:    assert len(bars) == 100, (name, len(bars))    total = 0    for bar_index, events in enumerate(bars):        starts = []        for event in events:            assert len(event) == 3, (name, bar_index, event)            slot, duration, midi = event
